import re
from json import loads

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.netactnode.genericnetactnode import GenericNetActNodeCommand


class Pnpclimx(GenericNetActNodeCommand):
    """Pnpclimx command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Pnpclimx command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Pnpclimx, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.current_ret["LINES"] = {}
        self._mapping = {}
        self._current_index = None

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "/opt/oss/Nokia-pnpautoconnection/bin/pnpclimx.sh"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise.
        :return: None.
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_line(line)
            except ParsingDone:
                pass
        super(Pnpclimx, self).on_new_line(line, is_full_line)

    # Unsupported operation: notSupported
    _re_parse_error = re.compile(r"(?P<ERROR>Unsupported operation:.*)")

    def _parse_error(self, line):
        """
        Parse line if error.

        :param line: Line from device.
        :return: None but raises ParsingDone if matches error.
        """
        if self._regex_helper.search_compiled(Pnpclimx._re_parse_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    # 11|Wed Aug 07 17:2|IDENTIFIED|{ | |{ | |POST_UPLOADED|
    _re_parse_correct_line = re.compile(r".*\|.*\|.*\|.*\|.*\|.*\|.*\|.*\|")

    def _parse_line(self, line):
        """
        Parse single line.

        :param line: Line from device.
        :return: None.
        """
        if self._regex_helper.search_compiled(Pnpclimx._re_parse_correct_line, line) and "Target Agent" in line:
            self._create_mapping(line)
        elif self._regex_helper.search_compiled(Pnpclimx._re_parse_correct_line, line):
            self._concatenate_column_content(line)

    def _create_mapping(self, line):
        """
        Create mapping between name of column and  based on first line.

        :param line: Line from device.
        :return: None.
        """
        split_line = line.split("|")
        for idx, item in enumerate(split_line):
            if item:
                self._mapping[idx] = item.strip()

    def _concatenate_column_content(self, line):
        """
        Concatenate content of each line in column for each row and assign it to correct key in dictionary.

        :param line: Line from device.
        :return: None.
        """
        split_line = line.split("|")
        for idx, item in enumerate(split_line):
            item = item.strip()
            if idx == 0 and item and item not in self.current_ret["LINES"]:
                self.current_ret["LINES"][item] = {}
                self._current_index = item
            if idx in self._mapping and self._mapping[idx] not in self.current_ret["LINES"][self._current_index]:
                self.current_ret["LINES"][self._current_index][self._mapping[idx]] = ""
            if idx in self._mapping:
                self.current_ret["LINES"][self._current_index][self._mapping[idx]] += item

    def on_success(self):
        """
        Run method _eval_dict when command is about to finish.

        :return: None.
        """
        self._eval_dict()

    def _eval_dict(self):
        """
        Change dictionary as string to python object as dict.

        :return: None.
        """
        for _, item in self.current_ret["LINES"].items():
            for name in ["Identification", "Temporary Agent", "Target Agent", "Final Target Agent"]:
                if item[name]:
                    item[name] = loads(item[name])


